import { ITEM_DEFS } from "./definitions/items.js";
import { session } from "./runtime/session.js";
import {
  attack, eat, equip, MONSTER_DEFS, monsters, nextRandom, spawnMonster,
} from "./systems/combat-system.js";
import { craft } from "./systems/crafting-system.js";
import { pickup } from "./systems/inventory-system.js";
import type { GameInput, GameSnapshot, LogEntry, MonsterInstance, MonsterKind, World } from "./types/game.js";
export type { GameInput, LogEntry, GameOutput, World, ItemKind, MonsterKind } from "./types/game.js";
export { ITEM_DEFS } from "./definitions/items.js";
export { monsters };

function say(message: string): void { session.eventLog.entries.push({ tick: session.tickCount, message }); }
function emit(text: string): void { if (session.worldRef) session.worldRef.output.push({ kind: "text", text }); }
function emitPanel(): void { if (session.worldRef) session.worldRef.output.push({ kind: "panel", text: debugDump() }); }
function schedule(at: number, message: string, damage: number): void { session.pendingEvents.push({ at, message, damage }); }
function onKey(input: GameInput): void {
  if (!session.vitals.alive) return;
  if (input === "KeyW") pickup("wood", say, emit); if (input === "KeyS") pickup("stone", say, emit);
  if (input === "KeyC") craft("torch", say, emit); if (input === "KeyQ") craft("ration", say, emit);
  if (input === "KeyF") attack(say, emit); if (input === "KeyE") eat(say, emit);
  if (input === "KeyH") {
    emitPanel();
    if (session.equipment.weapon === "fists" && session.inventory.items.torch > 0) {
      equip("torch", say, emit);
    }
  }
}
function tick(): void {
  const s = session, v = s.vitals; s.tickCount += 1;
  if (s.tickCount % 5 === 0) { v.hp -= 2; if (v.hp <= 0 && v.alive) { v.alive = false; say("you starve"); } }
  if (s.combat.torchBuffTicks > 0) s.combat.torchBuffTicks -= 1;
  const due = s.pendingEvents.filter((e) => e.at === s.tickCount);
  for (const e of due) { say(e.message); emit("event"); v.hp -= e.damage; if (v.hp <= 0 && v.alive) { v.alive = false; say("you die of your wounds"); } }
  s.pendingEvents = s.pendingEvents.filter((e) => e.at !== s.tickCount);
  for (const m of monsters) { if (m.kind === "crawler" && s.tickCount % 3 === 0) v.hp -= 1; if (m.kind === "stalker") { v.hp -= 3; if (v.hp <= 0 && v.alive) { v.alive = false; say(`the ${MONSTER_DEFS.stalker.name} finishes you`); } } }
  if (s.tickCount % 20 === 0 && s.eventLog.entries.length % 2 === 0) {
    spawnMonster(nextRandom() > 0.5 ? "stalker" : "crawler", say);
  }
  if (s.tickCount % 10 === 0) persist(snapshot(), s.worldRef);
}
function runTicks(count: number): void { for (let i = 0; i < count; i += 1) tick(); }
function decideUseStorage(): boolean { return !!session.worldRef && session.worldRef.storage.get("ventralis:save") !== undefined; }
function persist(data: GameSnapshot, world: World | null): void { if (!world || !decideUseStorage()) return; session.saveCounter += 1; world.storage.set("ventralis:save", JSON.stringify({ ...data, savedAtTick: session.tickCount, saveCounter: session.saveCounter })); }
function snapshot(): GameSnapshot {
  const s = session;
  return { tickCount: s.tickCount, hp: s.vitals.hp, maxHp: s.vitals.maxHp, wood: s.resources.wood, stone: s.resources.stone, inventory: { ...s.inventory.items }, equippedWeapon: s.equipment.weapon, attackBonus: s.combat.attackBonus, torchBuffTicks: s.combat.torchBuffTicks, alive: s.vitals.alive, log: s.eventLog.entries.slice(-20), monsters: monsters.map((m) => ({ ...m })), rngState: s.rngState };
}
function restore(raw: string): void {
  const d = JSON.parse(raw) as GameSnapshot, s = session;
  s.tickCount = d.tickCount as number; s.vitals.hp = d.hp as number; s.vitals.maxHp = d.maxHp as number; s.resources.wood = d.wood as number; s.resources.stone = d.stone as number; s.inventory.items = d.inventory as typeof s.inventory.items; s.equipment.weapon = d.equippedWeapon as string; s.combat.attackBonus = d.attackBonus as number; s.combat.torchBuffTicks = d.torchBuffTicks as number; s.vitals.alive = d.alive as boolean;
  s.eventLog.entries = (d.log as LogEntry[]).map((entry) => ({ ...entry })); monsters.length = 0; for (const m of d.monsters as MonsterInstance[]) monsters.push({ ...m }); s.rngState = d.rngState as number; say("save restored");
}
function debugDump(): string {
  const s = session, i = s.inventory.items;
  return [`tick=${s.tickCount}`, `hp=${s.vitals.hp}/${s.vitals.maxHp}`, `wood=${s.resources.wood}`, `stone=${s.resources.stone}`, `inv=${i.wood}/${i.stone}/${i.torch}/${i.ration}`, `weapon=${s.equipment.weapon}`, `bonus=${s.combat.attackBonus}`, `buff=${s.combat.torchBuffTicks}`, `alive=${s.vitals.alive}`, `monsters=${monsters.length}`, `events=${s.pendingEvents.length}`, `saves=${s.saveCounter}`].join(";");
}
export function resetGame(seed: number): void { session.reset(seed); }
export function initGame(world: World): void { session.worldRef = world; if (decideUseStorage()) { const raw = world.storage.get("ventralis:save"); if (raw) restore(raw); } say("you wake in the caverns of Ventralis"); }
export const gameLoop = tick;
export const keys = onKey;
export const api = {
  run: runTicks,
  pickup: (kind: Parameters<typeof pickup>[0]) => pickup(kind, say, emit),
  craft: (name: string) => craft(name, say, emit),
  consumeRation: () => eat(say, emit),
  equip: (item: string) => equip(item, say, emit),
  spawn: (kind: MonsterKind) => spawnMonster(kind, say),
  schedule,
  dump: debugDump,
  snapshot,
  restore,
  state: () => ({
    get tick() { return session.tickCount; },
    get hp() { return session.vitals.hp; },
    get alive() { return session.vitals.alive; },
    get wood() { return session.resources.wood; },
    get stone() { return session.resources.stone; },
  }),
};

import { defaultCombatModifiers, defaultEquipment, defaultEventLog, defaultInventory, defaultResourceMirror, defaultVitals } from "../components/player.js";
import type { CombatModifiers, Equipment, EventLog, Inventory, ResourceMirror, Vitals } from "../components/player.js";
import type { MonsterInstance, ScheduledEvent, World } from "../types/game.js";

export class GameSession {
  tickCount = 0;
  vitals: Vitals = defaultVitals();
  inventory: Inventory = defaultInventory();
  resources: ResourceMirror = defaultResourceMirror();
  equipment: Equipment = defaultEquipment();
  combat: CombatModifiers = defaultCombatModifiers();
  eventLog: EventLog = defaultEventLog();
  monsters: MonsterInstance[] = [];
  pendingEvents: ScheduledEvent[] = [];
  rngState = 1;
  saveCounter = 0;
  worldRef: World | null = null;

  reset(seed: number): void {
    this.tickCount = 0;
    this.vitals = defaultVitals(); this.inventory = defaultInventory();
    this.resources = defaultResourceMirror(); this.equipment = defaultEquipment();
    this.combat = defaultCombatModifiers(); this.eventLog = defaultEventLog();
    this.pendingEvents = []; this.saveCounter = 0; this.monsters.length = 0;
    this.rngState = seed >>> 0;
  }
}

export const session = new GameSession();

export type ItemKind = "wood" | "stone" | "torch" | "ration";
export type MonsterKind = "crawler" | "stalker";
export type GameInput = "KeyW" | "KeyS" | "KeyE" | "KeyF" | "KeyC" | "KeyQ" | "KeyH";
export interface LogEntry { tick: number; message: string; }
export interface GameOutput { kind: "text" | "panel"; text: string; }
export interface World {
  canvas: { width: number; height: number };
  storage: Map<string, string>;
  clock: () => number;
  output: GameOutput[];
}
export interface ItemDef { kind: ItemKind; name: string; weight: number; }
export interface MonsterDef { kind: MonsterKind; name: string; hp: number; attack: number; }
export interface MonsterInstance { kind: MonsterKind; hp: number; attack: number; }
export interface ScheduledEvent { at: number; message: string; damage: number; }
export type GameSnapshot = Record<string, unknown>;

import { session } from "../runtime/session.js";
import type { MonsterDef, MonsterInstance, MonsterKind } from "../types/game.js";

export const MONSTER_DEFS: Record<MonsterKind, MonsterDef> = {
  crawler: { kind: "crawler", name: "Crawler", hp: 10, attack: 4 },
  stalker: { kind: "stalker", name: "Stalker", hp: 16, attack: 7 },
};

export const monsters: MonsterInstance[] = session.monsters;

export function nextRandom(): number {
  session.rngState = (session.rngState * 1664525 + 1013904223) >>> 0;
  return session.rngState / 4294967296;
}

function rollInt(low: number, high: number): number {
  return low + Math.floor(nextRandom() * (high - low + 1));
}

function attackRoll(): number {
  let roll = rollInt(1, 20) + session.combat.attackBonus;
  if (session.combat.torchBuffTicks > 0) roll += 2;
  return roll;
}

export function eat(say: (message: string) => void, emit: (text: string) => void): void {
  const { vitals: v, inventory: { items: i } } = session;
  if (!v.alive) return;
  if (i.ration <= 0) {
    say("no rations left");
    emit("nothing to eat");
    return;
  }
  i.ration -= 1;
  v.hp = Math.min(v.maxHp, v.hp + 15 + i.torch);
  say("you eat a ration");
  emit("ate");
}

export function equip(item: string, say: (message: string) => void, emit: (text: string) => void): void {
  if (!session.vitals.alive) return;
  if (item === "torch" && session.inventory.items.torch > 0) {
    session.equipment.weapon = "torch";
    say("you ready the torch");
    emit("equipped torch");
  } else {
    session.equipment.weapon = "fists";
    say("you ready your fists");
    emit("equipped fists");
  }
}

export function spawnMonster(kind: MonsterKind, say: (message: string) => void): void {
  const d = MONSTER_DEFS[kind];
  monsters.push({ kind, hp: d.hp, attack: d.attack });
  say(`a ${d.name} emerges from the dark`);
}

export function attack(say: (message: string) => void, emit: (text: string) => void): void {
  if (!session.vitals.alive) return;
  if (!monsters.length) {
    say("nothing to attack");
    emit("swing at air");
    return;
  }
  const target = monsters[0];
  const roll = attackRoll();
  const d = MONSTER_DEFS[target.kind];
  if (roll >= 12) {
    target.hp -= 6 + session.combat.attackBonus;
    say(`you strike the ${d.name} (roll ${roll})`);
    if (target.hp <= 0) {
      monsters.shift();
      session.resources.stone += 2;
      session.inventory.items.stone += 2;
      say(`the ${d.name} falls`);
    }
  } else {
    say(`you miss the ${d.name} (roll ${roll})`);
  }
  emit(`attack roll ${roll}`);
}

